<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { RouterLink,useRoute,useRouter } from 'vue-router'
import { api,ApiError,date,money,type Customer,type Detail } from '../api'
import { reserveCommand,reservationPending,reservationBusy } from '../reservations'
import WaitingRoom from '../components/WaitingRoom.vue'
import ReservationPending from '../components/ReservationPending.vue'
import { purchaseCommand } from '../purchases'
import { attemptCommand } from '../stockAttempts'
const route=useRoute(),router=useRouter(),customer=ref<Customer|null>(null),detail=ref<Detail|null>(null),quantity=ref(1),error=ref(''),loading=ref(false),eligible=ref(false)
const mode=ref<'predebit'|'async'|'sync'>('sync')
const session=computed(()=>detail.value?.sessions.find(s=>s.tickets.some(t=>t.id===route.params.ticketId)))
const ticket=computed(()=>session.value?.tickets.find(t=>t.id===route.params.ticketId))
const canReserve=computed(()=>detail.value?.orderingEnabled&&(!detail.value.waitingRoomEnabled||eligible.value)&&session.value?.salesStatus==='SELLING'&&ticket.value&&ticket.value.available>=quantity.value)
async function load(){loading.value=true;error.value='';detail.value=null;eligible.value=false;try{customer.value=await api<Customer>('/customer/auth/me');detail.value=await api<Detail>('/public/events/'+route.params.eventId);mode.value=detail.value.preDebitEnabled?'predebit':detail.value.purchaseRequestsEnabled?'async':'sync'}catch(e){if(e instanceof ApiError&&e.status===401)await router.replace({path:'/account/login',query:{returnTo:route.path}});else error.value=(e as Error).message}finally{loading.value=false}}
async function submit(){if(!customer.value||!ticket.value||!canReserve.value||reservationPending.value||reservationBusy.value)return;error.value='';try{const body={ticketId:ticket.value.id,quantity:quantity.value,expectedTicketVersion:ticket.value.version,expectedTotalTwd:ticket.value.priceTwd*quantity.value};if(mode.value==='predebit'){if(!detail.value?.preDebitEnabled)return;const progress=await attemptCommand(customer.value,body);if(progress.purchase)await router.push('/account/purchases')}else if(mode.value==='async'){if(!detail.value?.purchaseRequestsEnabled)return;await purchaseCommand(customer.value,'/customer/purchases',body);await router.push('/account/purchases')}else{await reserveCommand(customer.value,'/customer/orders',body);await router.push('/account/orders')}}catch(e){error.value=(e as Error).message}}
function confirmed(kind:'purchase'|'order'){void router.push(kind==='purchase'?'/account/purchases':'/account/orders')}
onMounted(load)
</script>
<template><section class="content detail-page"><RouterLink :to="'/events/'+route.params.eventId" class="back-link">← 活動資訊</RouterLink><div class="event-title"><div class="eyebrow">RESERVE YOUR MOMENT</div><h1>先為你保留位置。</h1></div><ReservationPending :customer="customer" @confirmed="confirmed"/><p v-if="error" class="notice error" role="alert">{{error}} <button :disabled="loading||reservationBusy" @click="load">重新核對票額</button></p><p v-if="loading">讀取中…</p><article v-if="ticket&&session&&detail" class="panel"><h2>{{detail.event.title}}</h2><p>{{session.name}} · {{date(session.startsAt)}}</p><h3>{{ticket.name}} · {{money(ticket.priceTwd)}}</h3><p class="muted">目前剩餘 {{ticket.available}} 張 · 此票種每人限購 {{ticket.maxPerCustomer}} 張（含已付款與未釋放的保票）。票額以下單結果為準。</p><WaitingRoom v-if="detail.waitingRoomEnabled&&customer" :key="customer.id+ticket.id" :customer="customer" :ticket-id="ticket.id" @eligible="eligible=$event"/><form @submit.prevent="submit"><fieldset :disabled="reservationBusy||!!reservationPending||(detail.waitingRoomEnabled&&!eligible)"><label v-if="detail.purchaseRequestsEnabled">購票方式<select v-model="mode"><option v-if="detail.preDebitEnabled" value="predebit">預扣後送出購票請求</option><option value="async">先送出購票請求</option><option value="sync">直接確認保票</option></select></label><label>保票張數<input v-model.number="quantity" type="number" min="1" :max="Math.min(ticket.maxPerCustomer,ticket.available)" step="1" required></label><p class="reservation-total">合計 {{money(ticket.priceTwd*quantity)}}</p><p v-if="mode==='predebit'" class="notice">送出後先核對原購票操作。暫時預扣仍不代表正式保票，也沒有付款倒數；正式訂單成立後才可付款。</p><p v-else-if="mode==='async'" class="notice">送出後先顯示處理中，尚未保留票額。確認建立訂單後才開始付款倒數；請到本人購票紀錄核對結果。</p><p v-else class="notice">保留最多 10 分鐘，售票截止前到期。這是展示保票，付款僅限免費模擬（需開啟）；沒有真收款；電子票券需模擬付款確認後另行領取。</p><button class="primary" :disabled="!canReserve||!Number.isInteger(quantity)||quantity<1">{{mode==='predebit'?'預扣並送出購票請求 →':mode==='async'?'送出購票請求 →':'確認保票 →'}}</button></fieldset></form><p v-if="!canReserve" class="muted">{{detail.waitingRoomEnabled&&!eligible?'請先在等候室取得有效入場資格。':'目前未開放保票或票額不足，請重新核對。'}}</p></article><p v-else-if="detail&&!loading" class="notice error">找不到此票種。</p></section></template>
